//! Gap 3 (unreleased): the Rust TTL-aware graph feed.
//!
//! Fixture logs are built byte by byte (`ttl_log`) with a fixed lineage and
//! logged reclaim clocks, so every expected value below is a literal written
//! by hand, never output regenerated by the feed under test.

mod ttl_log;

use tempfile::tempdir;
use ttl_log::reclaim_fixture;
use vlite::changes::{Change, ChangeBatch, ChangeKind, FeedCursor, GraphChange, read_log_changes};
use vlite::changes::{
    GraphEventSet, GraphFeedBatch, GraphFeedCursor, GraphFeedError, read_log_graph_changes,
};
use vlite::{Database, Error, Metadata, Record};

const LINEAGE: u64 = ttl_log::LINEAGE;

fn change(sequence: u64, ordinal: u32, collection: &str, kind: ChangeKind) -> Change {
    Change {
        sequence,
        ordinal,
        collection: collection.into(),
        committed_at_ms: None,
        kind,
    }
}

fn batch(sequence: u64, operations: Vec<GraphChange>) -> Change {
    change(
        sequence,
        0,
        "",
        ChangeKind::GraphBatch {
            graph: "g".into(),
            revision: sequence,
            operations,
        },
    )
}

fn put(sequence: u64, id: u64, vector: [f32; 2], payload: &[u8]) -> Change {
    change(
        sequence,
        0,
        "default",
        ChangeKind::Put {
            id,
            record: Record {
                vector: vector.to_vec(),
                payload: payload.to_vec(),
                metadata: Metadata::new(),
            },
            expires_at_ms: None,
        },
    )
}

fn node(id: u64, key: &str, labels: &[&str], created: bool) -> GraphChange {
    GraphChange::NodeUpserted {
        id,
        key: key.into(),
        labels: labels.iter().map(|label| (*label).to_owned()).collect(),
        properties: Metadata::new(),
        created,
    }
}

fn edge(
    id: u64,
    key: Option<&str>,
    (source, source_key): (u64, &str),
    relationship: &str,
    (destination, destination_key): (u64, &str),
) -> GraphChange {
    GraphChange::EdgeUpserted {
        id,
        key: key.map(str::to_owned),
        source,
        source_key: source_key.into(),
        relationship: relationship.into(),
        destination,
        destination_key: destination_key.into(),
        properties: Metadata::new(),
        created: true,
    }
}

fn attachment(attached: bool, node: u64, node_key: &str, record: u64) -> GraphChange {
    let (node_key, collection) = (node_key.to_owned(), "default".to_owned());
    if attached {
        GraphChange::Attached {
            node,
            node_key,
            collection,
            record,
        }
    } else {
        GraphChange::Detached {
            node,
            node_key,
            collection,
            record,
        }
    }
}

/// The complete default-set (legacy) feed of `reclaim_fixture`, by hand:
/// deadlines and reclaims are omitted, so commits 5 and 8 are eventless and
/// the reclaimed node, edges and attachment never appear; the reclaim before
/// the drop of commit 13 leaves only `GraphDropped`.
fn legacy_expected() -> Vec<Change> {
    vec![
        put(1, 1, [1.0, 0.0], b"r1"),
        put(2, 2, [0.0, 1.0], b"r2"),
        change(3, 0, "", ChangeKind::GraphCreated { graph: "g".into() }),
        batch(
            4,
            vec![
                node(0, "a", &[], true),
                node(1, "b", &[], true),
                node(2, "c", &[], true),
                edge(0, Some("ab"), (0, "a"), "KNOWS", (1, "b")),
                edge(1, None, (1, "b"), "SELF", (1, "b")),
                edge(2, None, (0, "a"), "KNOWS", (2, "c")),
                attachment(true, 0, "a", 1),
            ],
        ),
        batch(
            6,
            vec![GraphChange::NodePatched {
                id: 1,
                key: "b".into(),
                add_labels: vec!["X".into()],
                remove_labels: vec![],
                set: Metadata::new(),
                unset: vec![],
            }],
        ),
        batch(
            7,
            vec![node(3, "a", &[], true), attachment(true, 3, "a", 1)],
        ),
        batch(9, vec![edge(3, Some("ca"), (2, "c"), "KNOWS", (3, "a"))]),
        batch(10, vec![node(2, "c", &["Kept"], false)]),
        batch(
            11,
            vec![
                GraphChange::EdgeDeleted {
                    id: 3,
                    key: Some("ca".into()),
                },
                attachment(false, 3, "a", 1),
                GraphChange::NodeDeleted {
                    id: 3,
                    key: "a".into(),
                },
            ],
        ),
        change(12, 0, "default", ChangeKind::Delete { id: 1 }),
        change(13, 0, "", ChangeKind::GraphDropped { graph: "g".into() }),
        change(14, 0, "", ChangeKind::GraphCreated { graph: "g".into() }),
        Change {
            ordinal: 1,
            ..batch(14, vec![node(0, "a", &[], true)])
        },
    ]
}

/// `(input sequence, events, next sequence, has_more, head, literal next
/// token)` of every one-event page from the beginning: pages hold whole
/// commits, an eventless commit directly after a page's last event is
/// consumed with it (5 and 8), commit 14's two events are one page, and a
/// full page's head is the commit that did not fit.
/// One literal page row; see [`ONE_EVENT_PAGES`].
type Page = (u64, &'static [(u64, u32)], u64, bool, u64, &'static str);

